exercise.solution:
use std::collections::HashMap;

fn main() {
    let mut results: HashMap<String, u64> = HashMap::new();
    let mut charges = 0u64;
    for key in ["k1", "k1", "k2"] {
        match results.get(key) {
            Some(v) => println!("{key}: replayed id {v}"),
            None => {
                charges += 1;
                results.insert(key.to_string(), charges);
                println!("{key}: charged as id {charges}");
            }
        }
    }
    println!("charges executed: {charges}");
}
